// import { User } from "features/users/pages/Users";



export type UserTypeFilter = "all" | "clients" | "bidders";
export type Status =
  | "active"
  | "suspended"
  | "pending"
  | "dormant";

export interface Column {
  label: string;
  key: keyof User;
}

export function deriveStatus(user: User): Status {
  if (user.is_active === false) return "suspended";
  return "active"; // default to active if field is missing, since most users are active
}
